    "sample identifier",
    "evaluation purpose",
    "target location",
    "disposal reason"
  ],
  "outputs": [
    "transfer approval",
    "updated sample status",
    "disposal record",
    "physical confirmation note"
  ],
  "activities": [
    {
      "id": "A1",
      "name": "Identify required sample and evaluation purpose",
      "actor": "sample requester"
    },
    {
      "id": "A2",
