      "actor": "verification engineer"
    },
    {
      "id": "A8",
      "name": "Approve and record disposal",
      "actor": "approver"
    }
  ],
  "decisions": [
    {
      "id": "D1",
      "condition": "Is the sample available and correctly identified?",
      "branches": [
        "available",
        "not found or mismatched"
      ]
    },
    {
      "id": "D2",
      "condition": "Is disposal allowed after evaluation?",
      "branches": [
        "allowed",
        "retain sample"
      ]
    }
  ],
  "exceptions": [
    "sample identifier mismatch",
    "missing physical sample",
    "approval delay",
    "retention requirement"
  ],
  "dependencies": [
